{"cards": [{"node_code": "N_41b8a26fb7db37ab", "definition": "专门用于破碎冰层、开辟航道或维持港口通航的特种船舶，涵盖其船体结构、动力配置、破冰原理及作业性能特征。", "boundary": "本节点聚焦于破冰船这一特定专业工作船类型。边界在于区分“破冰作业”与“普通航行”：若内容涉及船舶在冰区航行的操纵技术或导航，归入航海学；若涉及破冰船的总体设计、结构强度计算或建造工艺，归入船舶工程。本节点侧重破冰船的功能定位、类型分类（如破冰型、破冰辅助型）及典型代表。", "includes": ["破冰船的分类、功能定位及基本构造特征", "破冰原理、破冰能力指标及典型破冰船型介绍", "破冰船在极地或高纬度航道维护中的应用场景"], "excludes": ["破冰船的详细结构设计、强度计算及建造工艺", "船舶在冰区的驾驶操纵、导航技术及航海规则", "非破冰用途的普通运输船或工程船"], "sibling_distinctions": [{"other_code": "N_46f5627086252e6a", "rule": "区分依据为作业目的：本节点侧重通过物理破碎冰层以维持通航；兄弟节点侧重对遇险船舶、人员或货物的救援与打捞。"}, {"other_code": "N_7a0dfc1ad3f345f7", "rule": "区分依据为作业区域与对象：本节点侧重开阔水域或航道的破冰；兄弟节点侧重港口区域内的辅助作业（如拖带、引航、供水等）。"}], "cross_boundary_rule": "若内容涉及破冰船的设计原理或结构细节，主挂载“船舶工程”；若涉及破冰船的作业流程、类型特征或应用，主挂载本节点。"}, {"node_code": "N_6d97b6cbb01db6b3", "definition": "用于船舶维修、保养、焊接作业及海上工程支持的专业工作船，涵盖修理船、电焊工作船及类似辅助作业船舶的类型与特征。", "boundary": "本节点聚焦于“维修与焊接”功能的专业工作船。边界在于区分“海上维修”与“陆地修船”：若内容涉及船坞内的干船坞修理工艺，归入船舶修理工艺；若涉及海上风电安装等土建工程，归入工程船。本节点侧重船舶在浮态或半潜态下的维修、焊接、除锈、涂装等作业支持能力。", "includes": ["修理船、电焊工作船、除锈涂装船等维修类工作船的类型与特征", "海上焊接、维修作业的设备配置及作业环境要求", "用于船舶日常维护、小修及应急修理的专业船舶功能定位"], "excludes": ["陆地船坞内的干船坞修理工艺及设备", "以土建施工（如打桩、挖泥）为主要功能的工程船", "船舶的总体结构设计原理与详细建造工艺"], "sibling_distinctions": [{"other_code": "N_46f5627086252e6a", "rule": "区分依据为作业性质：本节点侧重对船舶本身的维护、修理与焊接；兄弟节点侧重对遇险目标的救援、打捞及人员救助。"}, {"other_code": "N_7a0dfc1ad3f345f7", "rule": "区分依据为功能定位：本节点侧重技术性维修作业（焊接、修理）；兄弟节点侧重港口运营辅助（拖带、引航、供水、消防等）。"}], "cross_boundary_rule": "若内容涉及海上风电安装等工程作业，主挂载“工程船”；若涉及船舶维修、焊接工艺及支持船舶，主挂载本节点。"}, {"node_code": "N_46f5627086252e6a", "definition": "用于海难事故中人员救助、船舶拖带、货物打捞及溢油清理等应急响应的专业船舶及配套装备，涵盖其类型、功能及作业特征。", "boundary": "本节点聚焦于“海难救助”功能的专业工作船及装备。边界在于区分“救助”与“工程”：若内容涉及沉船打捞的工程力学原理或大型起重船的施工能力，归入工程船；若涉及日常港口拖带，归入港务船。本节点侧重应急响应、人命救助、船舶脱困及海洋环境清理。", "includes": ["海难救助船、拖轮、打捞船、溢油回收船等救助类船舶的类型与特征", "海难救助装备（如救生艇、潜水装备、打捞工具）的功能与配置", "海难事故应急响应流程、救助作业技术及典型救助案例"], "excludes": ["以土建施工（如挖泥、打桩）为主要功能的工程船", "日常港口运营中的拖带、引航等港务作业", "船舶的总体结构设计原理与详细建造工艺"], "sibling_distinctions": [{"other_code": "N_41b8a26fb7db37ab", "rule": "区分依据为作业目的：本节点侧重对遇险目标的救援与打捞；兄弟节点侧重通过破碎冰层以维持通航。"}, {"other_code": "N_7a0dfc1ad3f345f7", "rule": "区分依据为作业性质：本节点侧重应急救助与打捞；兄弟节点侧重港口日常运营辅助（如拖带、引航、供水等）。"}], "cross_boundary_rule": "若内容涉及大型起重船的工程能力与施工原理，主挂载“工程船”；若涉及海难救助、人命救助、打捞作业及应急响应，主挂载本节点。"}]}
